import React, { useEffect, useState } from "react";
import Footer from "./Footer";
import Card from "./Card";
import Navbar from "./Navbar";
import { jwtDecode } from "jwt-decode";

function Shop({ onBuy, purchasedItems }) {
  const [items, setItems] = useState([]);
  const [currentUserId, setCurrentUserId] = useState(null);

  // Decode token
  useEffect(() => {
    const token = localStorage.getItem("token");

    if (token) {
      try {
        const decoded = jwtDecode(token);

        // ⚠️ Adjust this depending on how your backend signs the token
        setCurrentUserId(decoded.id); 
      } catch (err) {
        console.error("Invalid token:", err);
      }
    }
  }, []);

  // Fetch books
  useEffect(() => {
    fetch("http://localhost:5009/books")
      .then((res) => res.json())
      .then((data) => {
        setItems(data);
      })
      .catch((err) => console.error("Error fetching books:", err));
  }, []);

  // Filter out current user's books
  const filteredItems = items.filter(
    (item) => item.userId !== currentUserId
  );

  return (
    <>
      <Navbar />
      <div className="Body">
        {filteredItems.length === 0 ? (
           <div className="HeadMo">
             <p>No books available yet. Be the first to list one!</p>
           </div>  
        ) : (
          filteredItems.map((item) => (
            <Card
              key={item.id}
              pic={item.pic}
              title={item.title}
              para={item.para}
              price={item.price}
            >
              <button
                onClick={() => onBuy(item)}
                disabled={!!purchasedItems[item.id]}
                style={{
                  backgroundColor: purchasedItems[item.id]
                    ? "grey"
                    : "rgba(13, 110, 264, 1)",
                  color: "#fff",
                  borderRadius: "5px",
                  padding: "5px",
                  fontWeight: "100",
                  fontFamily: "Century Gothic",
                  width: "130px",
                }}
              >
                {purchasedItems[item.id] ? "Sold" : "Add to Cart"}
              </button>
            </Card>
          ))
        )}
      </div>
      <Footer />
    </>
  );
}

export default Shop;
